using UnityEngine;

public class WasteBin : MonoBehaviour
{
    [Header("Bin Settings")]
    [SerializeField] private string acceptedWasteType;
    [SerializeField] private AudioSource feedbackAudio;
    [SerializeField] private AudioClip successSound;
    [SerializeField] private AudioClip errorSound;

    private bool classificationCompleted = false;

    // Generated by AI - Sustainability integration and duplicate-action prevention
    public void TryDepositWaste(string playerWasteType)
    {
        // Prevent the same correct classification from adding progress repeatedly
        if (classificationCompleted)
        {
            Debug.Log("Waste has already been classified correctly in this bin.");
            return;
        }

        // Compare the waste carried by the player with the accepted waste type
        if (playerWasteType == acceptedWasteType)
        {
            classificationCompleted = true;

            Debug.Log("Correct waste classification! Increasing sustainability progress.");

            PlaySound(successSound);

            // Add sustainability progress to the global GameManager
            if (GameManager.Instance != null)
            {
                GameManager.Instance.AddSustainability(25f);
            }
        }
        else
        {
            Debug.Log("Incorrect classification! Waste rejected by the bin.");

            PlaySound(errorSound);
        }
    }

    // Plays the corresponding accessible audio feedback
    private void PlaySound(AudioClip clip)
    {
        if (feedbackAudio != null && clip != null)
        {
            feedbackAudio.PlayOneShot(clip);
        }
    }
}